BEGIN;
SET LOCAL lock_timeout = '5s';
CREATE SCHEMA office_universe;

CREATE TABLE office_universe.source_registrations (state_code text NOT NULL CHECK(state_code ~ '^[A-Z]{2}$'), family text NOT NULL CHECK(family IN ('discovery','elections','finance','geography','officeholders')), source_key text NOT NULL UNIQUE, authority_tier text NOT NULL CHECK(authority_tier IN ('national_discovery','official','aggregator')), status text NOT NULL CHECK(status IN ('configured','authority_unavailable','contract_pending')), source_url text, refresh_profile text NOT NULL CHECK(refresh_profile IN ('weekly','nightly','daily','election_window')), updated_at timestamptz NOT NULL DEFAULT clock_timestamp(), PRIMARY KEY(state_code,family));
CREATE TABLE office_universe.raw_payloads (id text PRIMARY KEY, source_key text NOT NULL, snapshot_id text NOT NULL, payload_sha256 text NOT NULL CHECK(payload_sha256 ~ '^[a-f0-9]{64}$'), payload_locator text NOT NULL CHECK(payload_locator !~ '^/' AND payload_locator !~ '\\' AND payload_locator !~ '(^|/)\\.\\.?(/|$)'), source_natural_key text, kind text NOT NULL CHECK(kind IN ('jurisdiction','body','office','term','holder','contest','result','filing','calendar','finance','geography')), observed_at timestamptz NOT NULL, received_at timestamptz NOT NULL DEFAULT clock_timestamp(), disposition text NOT NULL CHECK(disposition IN ('accepted','quarantined')), payload jsonb NOT NULL, UNIQUE NULLS NOT DISTINCT(source_key,snapshot_id,payload_sha256,source_natural_key,kind));
CREATE INDEX ou_raw_payloads_source_observed_idx ON office_universe.raw_payloads(source_key,observed_at);
CREATE TABLE office_universe.intake_issues (id text PRIMARY KEY, raw_payload_id text NOT NULL, source_natural_key text, code text NOT NULL, diagnostic text NOT NULL CHECK(diagnostic !~* '(address|contributor)'), retry_state text NOT NULL DEFAULT 'pending' CHECK(retry_state IN ('pending','retried','resolved','ignored')), created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE INDEX ou_intake_issues_payload_idx ON office_universe.intake_issues(raw_payload_id);
CREATE TABLE office_universe.jurisdictions (id text PRIMARY KEY, parent_jurisdiction_id text, state_code text, kind text NOT NULL, source_natural_key text NOT NULL, source_name text NOT NULL, effective_from date, effective_to date CHECK(effective_to IS NULL OR effective_from IS NULL OR effective_to>=effective_from), source_snapshot_id text NOT NULL, CHECK(parent_jurisdiction_id IS NULL OR parent_jurisdiction_id<>id), UNIQUE(source_snapshot_id,source_natural_key));
CREATE INDEX ou_jurisdictions_parent_idx ON office_universe.jurisdictions(parent_jurisdiction_id);
CREATE TABLE office_universe.governing_bodies (id text PRIMARY KEY, jurisdiction_id text NOT NULL, source_natural_key text NOT NULL, source_name text NOT NULL, normalized_name text NOT NULL, selection_method text NOT NULL CHECK(selection_method IN ('elected','appointed','ex_officio','mixed','unknown')), source_snapshot_id text NOT NULL, UNIQUE(source_snapshot_id,source_natural_key));
CREATE INDEX ou_bodies_jurisdiction_idx ON office_universe.governing_bodies(jurisdiction_id);
CREATE TABLE office_universe.offices (id text PRIMARY KEY, jurisdiction_id text NOT NULL, governing_body_id text, catalog_scope text NOT NULL, level text NOT NULL, office_family text NOT NULL, source_natural_key text NOT NULL, source_native_title text NOT NULL, normalized_title text NOT NULL, selection_method text NOT NULL, partisan_status text NOT NULL, election_method text NOT NULL, district_magnitude integer CHECK(district_magnitude IS NULL OR district_magnitude>0), source_snapshot_id text NOT NULL, UNIQUE(source_snapshot_id,source_natural_key));
CREATE INDEX ou_offices_jurisdiction_idx ON office_universe.offices(jurisdiction_id);
CREATE TABLE office_universe.terms (id text PRIMARY KEY, office_id text NOT NULL, starts_at timestamptz, ends_at timestamptz CHECK(ends_at IS NULL OR starts_at IS NULL OR ends_at>starts_at), selection_method text NOT NULL, source_snapshot_id text NOT NULL);
CREATE INDEX ou_terms_office_idx ON office_universe.terms(office_id,starts_at);
CREATE TABLE office_universe.holder_observations (id text PRIMARY KEY, office_id text NOT NULL, holder_id text, status text NOT NULL CHECK(status IN ('holder_pending_transition','current_holder','vacant','unknown','superseded')), effective_at timestamptz NOT NULL, source_snapshot_id text NOT NULL, supersedes_id text);
CREATE INDEX ou_holder_observations_office_effective_idx ON office_universe.holder_observations(office_id,effective_at);
CREATE TABLE office_universe.contests (id text PRIMARY KEY, office_id text, jurisdiction_id text, source_natural_key text NOT NULL, election_date date, round text NOT NULL, source_snapshot_id text NOT NULL, CHECK(office_id IS NOT NULL OR jurisdiction_id IS NOT NULL), UNIQUE(source_snapshot_id,source_natural_key));
CREATE INDEX ou_contests_election_date_idx ON office_universe.contests(election_date);
CREATE TABLE office_universe.result_observations (id text PRIMARY KEY, contest_id text NOT NULL, source_natural_key text NOT NULL, observed_at timestamptz NOT NULL, maturity text NOT NULL CHECK(maturity IN ('raw','normalized','reported_result','provisional_winner','certified_winner','superseded')), winner_candidate_key text, reporting_completeness_percent numeric CHECK(reporting_completeness_percent IS NULL OR (reporting_completeness_percent>=0 AND reporting_completeness_percent<=100)), source_snapshot_id text NOT NULL, supersedes_id text);
CREATE INDEX ou_result_observations_contest_observed_idx ON office_universe.result_observations(contest_id,observed_at);
CREATE TABLE office_universe.fact_observations (id text PRIMARY KEY, office_id text NOT NULL, fact_key text NOT NULL, maturity text NOT NULL, value jsonb, missing_reason text, effective_at timestamptz, source_snapshot_id text NOT NULL, CHECK((value IS NULL)<>(missing_reason IS NULL)));
CREATE INDEX ou_facts_office_key_idx ON office_universe.fact_observations(office_id,fact_key,effective_at);
CREATE TABLE office_universe.formula_programs (id text PRIMARY KEY, version text NOT NULL, workspace text NOT NULL CHECK(workspace IN ('provisional','certified')), required_fact_keys jsonb NOT NULL, eligibility jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT clock_timestamp(), UNIQUE(id,version));
CREATE TABLE office_universe.calculation_runs (id text PRIMARY KEY, formula_program_id text NOT NULL, formula_version text NOT NULL, workspace text NOT NULL CHECK(workspace IN ('provisional','certified')), source_cutoff timestamptz NOT NULL, calculated_at timestamptz NOT NULL DEFAULT clock_timestamp(), excluded_count integer NOT NULL DEFAULT 0 CHECK(excluded_count>=0), quarantined_count integer NOT NULL DEFAULT 0 CHECK(quarantined_count>=0));
CREATE INDEX ou_calculation_runs_program_cutoff_idx ON office_universe.calculation_runs(formula_program_id,source_cutoff);
CREATE TABLE office_universe.coverage (state_code text NOT NULL, office_family text NOT NULL, source_family text NOT NULL, status text NOT NULL CHECK(status IN ('observed','partial','unavailable','not_collected','catalog_only','quarantined')), expected_count integer NOT NULL, observed_count integer NOT NULL, raw_only_count integer NOT NULL, provisional_count integer NOT NULL, certified_count integer NOT NULL, quarantined_count integer NOT NULL, missingness jsonb NOT NULL, last_successful_refresh_at timestamptz, authority_tier text NOT NULL, PRIMARY KEY(state_code,office_family,source_family), CHECK(expected_count>=0 AND observed_count>=0 AND raw_only_count>=0 AND provisional_count>=0 AND certified_count>=0 AND quarantined_count>=0));

REVOKE ALL ON SCHEMA office_universe FROM PUBLIC;
GRANT USAGE ON SCHEMA office_universe TO dsa_seats_migration_owner,dsa_seats_ingest;
GRANT SELECT,INSERT,UPDATE,DELETE ON ALL TABLES IN SCHEMA office_universe TO dsa_seats_migration_owner,dsa_seats_ingest;
COMMIT;
